package com.personal.jobagent.automation;
import com.personal.jobagent.audit.*; import com.personal.jobagent.common.UuidV7; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api/v1/automation") public class AutomationController { private final AutomationPlanRepository plans; private final AuditLogWriter audit; public AutomationController(AutomationPlanRepository p,AuditLogWriter a){plans=p;audit=a;} public record CreateRequest(UUID applicationId,UUID jobId,String targetUrl,String idempotencyKey,List<AutomationPlan.Step> steps){} public record StepRequest(int index,String stepId,String status,Map<String,Object> result,String screenshotRef){} public record OutcomeRequest(String outcome,String detail){} public record WorkerEvent(String eventId,UUID planId,UUID applicationId,UUID jobId,String type,Map<String,Object> payload){} @PostMapping("/plans") public ResponseEntity<?> create(@RequestBody CreateRequest r){if(r.applicationId()==null||r.jobId()==null||r.targetUrl()==null||r.idempotencyKey()==null)return ResponseEntity.badRequest().body(Map.of("error","missing correlation or target"));UUID id=plans.create(r.applicationId(),r.jobId(),r.targetUrl(),r.idempotencyKey(),r.steps()==null?List.of():r.steps());audit.write(new AuditEntry("user","AUTOMATION_PLAN_CREATED","AUTOMATION_PLAN",id,null,Map.of("applicationId",r.applicationId().toString()),null,UuidV7.generate()));return ResponseEntity.ok(Map.of("planId",id,"status","PREPARED"));} @GetMapping("/plans/{id}") public ResponseEntity<?> get(@PathVariable UUID id){return plans.find(id).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());} @PostMapping("/plans/{id}/claim") public ResponseEntity<?> claim(@PathVariable UUID id){return plans.claim(id)?ResponseEntity.ok(Map.of("status","RUNNING")):ResponseEntity.status(409).body(Map.of("error","plan is not PREPARED"));} @PostMapping("/plans/{id}/heartbeat") public ResponseEntity<?> heartbeat(@PathVariable UUID id){return plans.heartbeat(id)?ResponseEntity.noContent().build():ResponseEntity.status(409).build();} @PostMapping("/plans/{id}/steps") public ResponseEntity<?> step(@PathVariable UUID id,@RequestBody StepRequest r){return plans.appendStep(id,r.index(),r.stepId(),r.status(),r.result()==null?Map.of():r.result(),r.screenshotRef())?ResponseEntity.noContent().build():ResponseEntity.notFound().build();} @PostMapping("/plans/{id}/approve-submit") public ResponseEntity<?> approve(@PathVariable UUID id){return plans.approveSubmit(id)?ResponseEntity.noContent().build():ResponseEntity.status(409).body(Map.of("error","submit approval requires AWAITING_SUBMIT_APPROVAL"));} @PostMapping("/plans/{id}/complete") public ResponseEntity<?> complete(@PathVariable UUID id,@RequestBody OutcomeRequest r){String o=r.outcome();boolean ok=switch(o==null?"":o){case "AWAITING_SUBMIT_APPROVAL","COMPLETED","FAILED","BLOCKED_ANTI_BOT"->plans.transition(id,"RUNNING",o);case "SUBMITTED"->plans.find(id).filter(p->p.submitApproved()).map(p->plans.transition(id,"RUNNING",o)).orElse(false);default->false;};if(!ok)return ResponseEntity.status(409).body(Map.of("error","illegal or unsafe transition"));audit.write(new AuditEntry("worker","AUTOMATION_PLAN_"+o,"AUTOMATION_PLAN",id,null,Map.of("detail",r.detail()==null?"":r.detail()),null,UuidV7.generate()));return ResponseEntity.noContent().build();} @PostMapping("/events") public ResponseEntity<?> event(@RequestBody WorkerEvent e){if(e.eventId()==null||e.type()==null||e.planId()==null)return ResponseEntity.badRequest().body(Map.of("error","event correlation required"));boolean fresh=plans.recordWorkerEvent(e.eventId(),e.planId(),e.applicationId(),e.jobId(),e.type(),e.payload()==null?Map.of():e.payload());return ResponseEntity.ok(Map.of("accepted",fresh,"replayed",!fresh));} @PostMapping("/plans/recover-stale") public Map<String,Object> recover(@RequestParam(defaultValue="15") long minutes){return Map.of("recovered",plans.recoverStale(Instant.now().minusSeconds(minutes*60)));} }